    function scoreBarline(features) {
        // We accumulate votes for class 0 and class 1
        var votes = [0, 0];
        
        for (var i = 0; i < modelData.length; i++) {
            var node = modelData[i];
            while (node.v === undefined) {
                if (features[node.f] <= node.t) {
                    node = node.l;
                } else {
                    node = node.r;
                }
            }
            // Leaf reached. Accumulate votes (tree.value array)
            votes[0] += node.v[0];
            votes[1] += node.v[1];
        }
        return votes;
    }

    function predictProbability(features) {
        var scores = scoreBarline(features);
        return scores[1] / 100;
    }

    return {
        scoreFeatures: scoreBarline,
        predictProbability: predictProbability,
        FEATURE_NAMES: ['blackness', 'connectivity', 'box_density_above', 'box_density_below', 'median_width', 'max_width', 'pct_wide', 'max_bound_width', 'left_white', 'right_white', 'left_contrast', 'right_contrast', 'local_density', 'grid_above_left', 'grid_above_center', 'grid_above_right', 'grid_top_left', 'grid_top_center', 'grid_top_right', 'grid_bot_left', 'grid_bot_center', 'grid_bot_right', 'grid_below_left', 'grid_below_center', 'grid_below_right', 'space_blob_left_1', 'space_blob_right_1', 'space_blob_left_2', 'space_blob_right_2', 'space_blob_left_3', 'space_blob_right_3', 'space_blob_left_4', 'space_blob_right_4']
    };
